\begin{tikzpicture}[scale=0.35, font=\sffamily, line cap=round, line join=round]
  \coordinate (B) at (0,0);
  \coordinate (D) at (0,8.97);
  \coordinate (C) at (4.08,7.06);
  \coordinate (A) at (-2.18,6.92);
  \coordinate (X) at (0,4.2);
  \coordinate (T) at (4.08,13.06);

  \draw (A) -- (B) -- (C) -- (D) -- cycle;
  \draw (B) -- (D);
  \draw[thick] (C) -- (T);
  \draw[dashed] (C) -- (X) -- (T);

  % angle marks drawn explicitly
  \draw ($(B)+(60:4)$) arc (60:90:4);
  \node at ($(B)+(75:5.5)$) {$30^\circ$};
  \draw ($(C)+(155.2:3)$) arc (155.2:240:3);
  \node at ($(C)+(197.6:4.8)$) {$85^\circ$};

  % lengths
  \node[left] at ($(A)!0.5!(B)$) {14.5 m};
  \node[left] at ($(A)!0.5!(D)$) {6 m};
  \node[right] at ($(C)!0.5!(D)$) {9 m};
  \node[right] at ($(C)!0.5!(T)$) {12 m};
  \node[right] at ($(B)!0.3!(D)$) {$BD$};

  % north arrow
  \draw[->] (-3,1) -- (-3,3) node[above] {$N$};

  \foreach \p in {A,B,C,D,X,T} \fill (\p) circle (2pt);
  \node[left] at (A) {$A$};
  \node[below] at (B) {$B$};
  \node[right] at (C) {$C$};
  \node[above left] at (D) {$D$};
  \node[left] at (X) {$X$};
  \node[right] at (T) {$T$};
\end{tikzpicture}

